import hashlib
import hmac

def secure_data_storage(data):
    # Generate a secret key for HMAC
    secret_key = hashlib.sha256("secret_key".encode()).digest()

    # Create a new HMAC object using the secret key and SHA-256
    hmac_object = hmac.new(secret_key, data.encode(), hashlib.sha256)

    # Return the hashed data
    return hmac_object.hexdigest()

